import {createV2} from './v2.js';
const icons = {
  grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  inbox:'<path d="M4 4h16l2 12v4H2v-4L4 4Z"/><path d="M2 15h6l2 3h4l2-3h6"/>',
  layers:'<path d="m12 3 10 5-10 5L2 8l10-5Z"/><path d="m2 12 10 5 10-5M2 16l10 5 10-5"/>',
  person:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
  userplus:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-2a7 7 0 0 1 12-5M19 10v8m-4-4h8"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  alert:'<path d="m10.3 4.2-8 14a2 2 0 0 0 1.7 3h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4m0 4h.01"/>',
  chart:'<path d="M4 3v18h18M8 15v-5m5 5V6m5 9v-7"/>',
  import:'<path d="M12 3v12m-4-4 4 4 4-4M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',
  settings:'<path d="M10 3h4l1 3 3 1 3-1 2 4-2 2v3l2 2-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-2v-3l-2-2 2-4 3 1 3-1 1-3Z" transform="translate(0 -1) scale(.95)"/><circle cx="11.5" cy="11" r="3"/>',
  plus:'<path d="M12 5v14M5 12h14"/>', search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',
  filter:'<path d="M4 7h16M7 12h10m-7 5h4"/><circle cx="8" cy="7" r="2" fill="currentColor" stroke="none"/><circle cx="15" cy="12" r="2" fill="currentColor" stroke="none"/>',
  mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',
  check:'<path d="m5 12 4 4L19 6"/>',checkcircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',
  refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1"/>',
  file:'<path d="M14 2H5v20h14V7l-5-5Z"/><path d="M14 2v6h5M8 13h8m-8 4h8"/>',
  link:'<path d="m10 13 4-4m-6 5-2 2a3 3 0 0 0 4 4l4-4a3 3 0 0 0 0-4m2-2 2-2a3 3 0 0 0-4-4l-4 4a3 3 0 0 0 0 4"/>',
  external:'<path d="M14 3h7v7m-1-6-9 9M10 4H4v16h16v-6"/>',
  comment:'<path d="M21 11a8 8 0 0 1-8 8H8l-5 3v-7a8 8 0 1 1 18-4Z"/>',
  history:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6M12 7v5l3 2"/>',
  move:'<path d="M14 4h7v7m-1-6-9 9M9 4H3v17h17v-6"/>',
  shield:'<path d="M12 3 3 6v6c0 5 9 9 9 9s9-4 9-9V6l-9-3Z"/><path d="m8 12 3 3 5-6"/>',
  database:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14a9 3 0 0 0 18 0V5M3 12a9 3 0 0 0 18 0"/>',
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',attachment:'<path d="m9 12 6-6a3 3 0 0 1 4 4l-9 9a5 5 0 0 1-7-7l9-9a6 6 0 0 1 9 9l-8 8"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>',
};
const ico = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.file}</svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const dateShort = value => value && !isNaN(new Date(value)) ? new Intl.DateTimeFormat('fr-FR',{day:'2-digit',month:'short'}).format(new Date(value)) : '—';
const dateFull = value => value && !isNaN(new Date(value)) ? new Intl.DateTimeFormat('fr-FR',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value)) : '—';
const initials = value => String(value || '?').split(/\s+/).filter(Boolean).slice(0,2).map(v=>v[0]).join('').toUpperCase();
const num = value => new Intl.NumberFormat('fr-FR').format(Number(value || 0));
const labelValue = item => typeof item === 'string' ? item : item.name ?? item.label ?? item.id ?? '';
const optionValues = (items, selected='', empty='Tous') => `${empty !== null ? `<option value="">${esc(empty)}</option>` : ''}${(items || []).map(item => {const value=labelValue(item);return `<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(value)}</option>`;}).join('')}`;
const statusClass = value => ({'Ouvert':'open','En cours':'progress','En attente':'waiting','Clos':'closed'})[value] || 'open';
const statusBadge = value => `<span class="badge status-${statusClass(value)}"><span class="dot"></span>${esc(value || 'Ouvert')}</span>`;
const priorityBadge = value => `<span class="priority ${esc(String(value||'Normale').toLowerCase())}"><span class="priority-mark"></span>${esc(value||'Normale')}</span>`;
const safeUrl = value => {try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:null;}catch{return null;}};
const userName = value => state.context?.users?.find(u=>u.id===value)?.name || value || '';
const defaultFilters = () => ({q:'',status:'',assignee:'',priority:'',source:'',application:'',category:'',from:'',to:'',sort:'updated_desc'});
const views = [
  {id:'active',label:'À traiter',icon:'inbox',count:'active'},
  {id:'all',label:'Toutes les demandes',icon:'layers',count:'total'},
  {id:'mine',label:'Mes demandes',icon:'person',count:'mine'},
  {id:'unassigned',label:'Sans affectation',icon:'userplus',count:'unassigned'},
  {id:'waiting',label:'En attente',icon:'clock',count:'waiting'},
  {id:'alerts',label:'Réponses à examiner',icon:'alert',count:'alerts'},
  {id:'closed',label:'Demandes closes',icon:'checkcircle',count:'closed'}
];
let savedWorkspace='demo';
try{savedWorkspace='demo';}catch{}
const state = {workspace:savedWorkspace,context:null,stats:{},view:'active',filters:defaultFilters(),items:[],total:0,selected:new Set(),moreFilters:false,detail:null,detailId:null,timeline:'all',listSeq:0,workspaceSeq:0,importKind:'mail',importFiles:[],importResult:null,modalReturn:null,drawerReturn:null,detailDirty:false};
const v2=createV2({state,api,$,$$,esc,ico,toast,openModal,closeModal,dateFull,num,boot,navigate,renderShell,renderPage,openDetail,download,heading});
let searchTimer,toastTimer;

async function api(path,{method='GET',body,blob=false,workspace=state.workspace}={}){
  const headers={'X-Vigie-Workspace':workspace};
  if(body!==undefined)headers['Content-Type']='application/json';
  if(method!=='GET')headers['X-CSRF-Token']=state.context?.csrf_token || '';
  let response;
  try{response=await fetch(path,{method,headers,body:body!==undefined?JSON.stringify(body):undefined,credentials:'same-origin'});}catch{throw new Error('Vigie est momentanément inaccessible. Vérifiez que le serveur local est démarré.');}
  if(!response.ok){if(response.status===401&&!path.startsWith('/api/auth/'))setTimeout(()=>v2.expired(),0);let data;try{data=await response.json();}catch{data={};}const error=new Error(data.message || (typeof data.error==='string'?data.error:data.error?.message) || `La demande n’a pas abouti (erreur ${response.status}).`);error.status=response.status;error.data=data;throw error;}
  if(blob){const disposition=response.headers.get('Content-Disposition')||'';let filename=disposition.match(/filename="?([^";]+)/)?.[1];const encoded=disposition.match(/filename\*=UTF-8''([^;]+)/i)?.[1];if(encoded){try{filename=decodeURIComponent(encoded);}catch{}}return {blob:await response.blob(),filename};}
  if(response.status===204)return null;
  return response.json();
}
function toast(message,error=false){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}" role="status">${ico(error?'alert':'checkcircle')}<span>${esc(message)}</span></div>`;toastTimer=setTimeout(()=>$('#toast-root').replaceChildren(),5000);}
function errorBox(error,retry='retry-list'){return `<div class="error-box" role="alert">${ico('alert')}<span>${esc(error.message||error)}</span>${retry?`<button class="button small" data-action="${retry}">Réessayer</button>`:''}</div>`;}
function modeBanner(){return `<div class="mode-banner">${ico(state.workspace==='demo'?'info':'database')}<span class="label">${state.workspace==='demo'?'DÉMONSTRATION':'ESPACE LOCAL'}</span><span>${state.workspace==='demo'?'Exemples fictifs. Modifications dans ce navigateur uniquement. Ne saisissez aucune donnée réelle.':'Données enregistrées sur ce poste. Outlook et l’identité d’entreprise ne sont pas connectés.'}</span></div>`;}
function heading(title,subtitle,action=true){return `<div class="page-heading"><div><div class="eyebrow">Pôle SAP · RIP</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action?`<button class="button primary" data-action="new">${ico('plus')}Nouvelle demande</button>`:''}</div>`;}
function pageFooter(){return `<div class="page-footer"><span>${ico('database')}Démonstration publique · données fictives · ${state.workspace==='demo'?'espace de démonstration':'espace de travail'}</span><span>Vigie <span class="footer-divider">/</span> Suivi des demandes SAP RIP</span></div>`;}
function renderShell(){
  const actor=state.context.actor || {name:'Utilisateur local',role:'admin'};
  $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar" aria-label="Navigation principale"><div class="brand"><span class="brand-symbol">V</span><div><div class="brand-name">vigie<span class="brand-accent">.</span></div><div class="brand-caption">Le suivi, en clair</div></div></div><div class="workspace-label">ESPACE DE TRAVAIL</div><nav class="nav-group">${views.map(v=>`<button class="nav-item ${state.view===v.id?'active':''}" data-view="${v.id}" ${state.view===v.id?'aria-current="page"':''}>${ico(v.icon)}<span class="nav-text">${v.label}</span><span class="nav-count ${v.id==='alerts'?'attention':''}" data-count="${v.count}">${num(state.stats[v.count])}</span></button>`).join('')}</nav><div class="nav-separator"></div><nav class="nav-group" aria-label="Pilotage et administration"><button class="nav-item" data-view="reporting">${ico('chart')}<span class="nav-text">Pilotage</span></button><button class="nav-item" data-view="imports">${ico('import')}<span class="nav-text">Imports & rapprochements</span><span class="nav-count attention" data-count="unresolved">${num(state.stats.unresolved)}</span></button><button class="nav-item" data-view="settings">${ico('settings')}<span class="nav-text">Paramètres</span></button></nav><div class="sidebar-footer"><div class="avatar">${esc(initials(actor.name))}</div><div><div class="actor-name">${esc(actor.name)}</div><div class="actor-role">Session locale · ${actor.role==='admin'?'administration':esc(actor.role)}</div></div></div></aside><div class="app-main"><header class="topbar"><button class="icon-button mobile-menu" aria-label="Ouvrir la navigation" data-action="menu">${ico('menu')}</button><div class="breadcrumb"><span>Pôle SAP</span><span class="crumb-section">/</span><strong class="crumb-section" id="breadcrumb-view">Demandes</strong></div><div class="top-actions"><span class="local-status"><span class="status-dot"></span>Application locale</span><label class="visually-hidden" for="workspace-select">Espace de données</label><select class="workspace-select" id="workspace-select"><option value="demo" ${state.workspace==='demo'?'selected':''}>Démonstration · données fictives</option><option value="local" ${state.workspace==='local'?'selected':''}>Espace local · mes données</option></select></div></header><main id="main" class="page-content" tabindex="-1"></main></div></div>`;
  v2.shell();renderPage();v2.decorate();
}
function updateNav(){
  $$('[data-view]').forEach(button=>{const active=button.dataset.view===state.view;button.classList.toggle('active',active);active?button.setAttribute('aria-current','page'):button.removeAttribute('aria-current');});
  $$('[data-count]').forEach(el=>el.textContent=num(state.stats[el.dataset.count]));
  if($('#breadcrumb-view'))$('#breadcrumb-view').textContent=({reporting:'Pilotage',imports:'Imports',settings:'Paramètres',admin:'Administration',designer:'Concepteur du site'})[state.view]||'Demandes';
}
function statsCards(){return `<div class="stats-grid">${[
  ['active','Demandes actives','inbox','Ouvertes, en cours et en attente'],['unassigned','Sans affectation','userplus','À attribuer à un membre du pôle'],['waiting','En attente','clock','Un suivi à garder en vue'],['alerts','Réponses à examiner','alert','Nouveaux échanges après clôture']
].map(([key,label,icon,hint])=>`<button class="stat-card ${state.view===key?'current':''}" data-view="${key}" aria-label="${esc(label)} : ${num(state.stats[key])}"><div class="stat-top"><span>${label}</span><span class="stat-icon">${ico(icon)}</span></div><div class="stat-number" data-stat="${key}">${state.stats[key]===undefined?'—':num(state.stats[key])}</div><div class="stat-bottom">${hint}</div></button>`).join('')}</div>`;}
function renderPage(){
  updateNav();if(v2.route(state.view))return;
  if(state.view==='reporting')return renderReporting();
  if(state.view==='imports')return renderImports();
  if(state.view==='settings')return renderSettings();
  $('#main').innerHTML=`${heading('Demandes','Une vue unique pour suivre chaque sollicitation, du premier échange à la clôture.')}${modeBanner()}<div id="stats-region">${statsCards()}</div><section class="list-panel" aria-label="Liste des demandes"><div class="list-toolbar"><div class="view-title">${esc(views.find(v=>v.id===state.view)?.label || 'Demandes')}<span class="count-pill" id="result-total">—</span></div><div class="toolbar-actions"><button class="button small" data-action="refresh" title="Actualiser les demandes">${ico('refresh')}<span>Actualiser</span></button><button class="button small" data-action="export" data-format="csv">${ico('import')}Exporter CSV</button></div></div><div class="search-row"><label class="search-box">${ico('search')}<span class="visually-hidden">Rechercher une demande</span><input id="search" type="search" placeholder="Rechercher un sujet, un RITM, un demandeur…" value="${esc(state.filters.q)}" autocomplete="off"></label><label class="visually-hidden" for="filter-status">Statut</label><select id="filter-status" data-filter="status">${optionValues(state.context.statuses,state.filters.status,'Tous les statuts')}</select><label class="visually-hidden" for="filter-assignee">Affectation</label><select id="filter-assignee" data-filter="assignee">${v2.assigneeOptions(state.filters.assignee)}</select><button class="button" data-action="filters" aria-expanded="${state.moreFilters}">${ico('filter')}Filtres${Object.entries(state.filters).filter(([k,v])=>!['q','sort','status','assignee'].includes(k)&&v).length?` (${Object.entries(state.filters).filter(([k,v])=>!['q','sort','status','assignee'].includes(k)&&v).length})`:''}</button></div><div id="more-filters" ${!state.moreFilters?'hidden':''}>${moreFiltersHTML()}</div><div id="filter-chips"></div><div id="selection-region"></div><div id="table-region">${loadingList()}</div><div class="table-footer"><span id="table-count">Chargement des demandes…</span><label><span class="visually-hidden">Trier les demandes</span><select class="sort-select" data-filter="sort"><option value="updated_desc" ${state.filters.sort==='updated_desc'?'selected':''}>Dernière activité ↓</option><option value="created_desc" ${state.filters.sort==='created_desc'?'selected':''}>Plus récentes d’abord</option><option value="oldest" ${state.filters.sort==='oldest'?'selected':''}>Plus anciennes d’abord</option><option value="priority" ${state.filters.sort==='priority'?'selected':''}>Priorité la plus haute</option></select></label></div></section>${pageFooter()}`;
  renderFilterChips();v2.decorate();loadList();
}
function moreFiltersHTML(){return `<div class="more-filters"><label>Priorité<select data-filter="priority">${optionValues(state.context.priorities,state.filters.priority,'Toutes les priorités')}</select></label><label>Source<select data-filter="source">${optionValues(['Outlook','Manuelle'],state.filters.source,'Toutes les sources')}</select></label><label>Application<select data-filter="application">${optionValues(state.context.applications,state.filters.application,'Toutes les applications')}</select></label><label>Catégorie<select data-filter="category">${optionValues(state.context.categories,state.filters.category,'Toutes les catégories')}</select></label><label>Créée à partir du<input type="date" data-filter="from" value="${esc(state.filters.from)}"></label><label>Créée jusqu’au<input type="date" data-filter="to" value="${esc(state.filters.to)}"></label><button class="button link small" data-action="clear-filters">Effacer les filtres</button></div>`;}
function renderFilterChips(){const region=$('#filter-chips');if(!region)return;const labels={q:'Recherche',status:'Statut',assignee:'Affectation',priority:'Priorité',source:'Source',application:'Application',category:'Catégorie',from:'Depuis',to:'Jusqu’au'};const active=Object.entries(state.filters).filter(([key,value])=>key!=='sort'&&value);region.innerHTML=active.length?`<div class="filter-chips">${active.map(([key,value])=>`<span class="filter-chip">${esc(labels[key])} : ${esc(value)}<button data-clear-filter="${key}" aria-label="Retirer le filtre ${esc(labels[key])}">${ico('close')}</button></span>`).join('')}<button class="button link small" data-action="clear-filters">Tout effacer</button></div>`:'';}
function queryString(extra={}){const p=new URLSearchParams({view:views.some(v=>v.id===state.view)?state.view:'all',...state.filters,...extra});if(state.filters.assignee){p.set('assignee_id',state.filters.assignee);p.delete('assignee');}[...p].forEach(([k,v])=>{if(v==='')p.delete(k);});return p.toString();}
function loadingList(){return `<div class="loading-table" role="status" aria-label="Chargement des demandes">${Array.from({length:6},()=>'<div class="skeleton"></div>').join('')}</div>`;}
async function loadStats(){if(!v2.can('requests.read'))return;const seq=state.workspaceSeq;try{const data=await api('/api/stats');if(seq!==state.workspaceSeq)return;state.stats=data;updateNav();if($('#stats-region'))$('#stats-region').innerHTML=statsCards();}catch(error){toast(error.message,true);}}
async function loadList(){
  const seq=++state.listSeq,ws=state.workspaceSeq;if(!$('#table-region'))return;
  $('#table-region').setAttribute('aria-busy','true');
  try{const result=await api(`/api/requests?${queryString()}`);if(seq!==state.listSeq||ws!==state.workspaceSeq||!$('#table-region'))return;state.items=result.items||[];state.total=result.total??state.items.length;const ids=new Set(state.items.map(x=>String(x.id)));state.selected=new Set([...state.selected].filter(x=>ids.has(x)));renderTable();}
  catch(error){if(seq!==state.listSeq||!$('#table-region'))return;$('#table-region').innerHTML=errorBox(error);$('#table-count').textContent='Chargement interrompu';$('#table-region').removeAttribute('aria-busy');}
}
function renderTable(){
  const region=$('#table-region');if(!region)return;region.removeAttribute('aria-busy');$('#result-total').textContent=num(state.total);$('#table-count').textContent=`${num(state.items.length)} demande${state.items.length>1?'s':''}${state.items.length!==state.total?` affichées sur ${num(state.total)}`:' dans cette vue'}`;
  if(!state.items.length){const localEmpty=state.workspace==='local'&&!Object.entries(state.filters).some(([k,v])=>k!=='sort'&&v);region.innerHTML=`<div class="empty-state">${ico(localEmpty?'inbox':'search')}<h3>${localEmpty?'Votre espace est prêt':'Aucune demande dans cette vue'}</h3><p>${localEmpty?'Créez votre première demande ou importez vos échanges pour commencer le suivi.':'Essayez une autre recherche, ajustez les filtres ou consultez toutes les demandes.'}</p><div style="display:flex;gap:10px">${localEmpty?'<button class="button primary" data-action="new">Créer une demande</button><button class="button" data-view="imports">Importer des données</button>':'<button class="button" data-action="clear-filters">Effacer les filtres</button><button class="button" data-view="all">Toutes les demandes</button>'}</div></div>`;renderSelection();return;}
  region.innerHTML=`<div class="table-wrap"><table><caption class="visually-hidden">Demandes SAP RIP. Sélectionnez une ligne pour l’exporter, ou ouvrez son intitulé pour la traiter.</caption><thead><tr><th><input id="select-all" type="checkbox" aria-label="Sélectionner toutes les demandes affichées" ${state.selected.size===state.items.length?'checked':''}></th><th scope="col">Demande</th><th scope="col">Statut</th><th scope="col" class="priority-col">Priorité</th><th scope="col">Affectation</th><th scope="col">RITM</th><th scope="col">Dernière activité</th><th scope="col"><span class="visually-hidden">Alertes</span></th></tr></thead><tbody>${state.items.map(r=>`<tr class="${state.selected.has(String(r.id))?'selected':''}"><td><input type="checkbox" data-select="${r.id}" aria-label="Sélectionner ${esc(r.reference)}" ${state.selected.has(String(r.id))?'checked':''}></td><td><div class="reference">${esc(r.reference || `VIG-${r.id}`)}</div><button class="request-title-button" data-open="${r.id}">${esc(r.title)}</button><div class="request-subtitle">${ico(r.source==='Outlook'?'mail':'file')}<span>${esc(r.requester || r.requester_email || r.source || 'Demande manuelle')}</span><span class="divider">·</span><span>${num(r.message_count)} message${r.message_count>1?'s':''}</span></div></td><td>${statusBadge(r.status)}</td><td class="priority-col">${priorityBadge(r.priority)}</td><td>${r.assignee?`<span class="assignee"><span class="avatar">${esc(initials(userName(r.assignee)))}</span><span>${esc(userName(r.assignee))}</span></span>`:'<span class="unassigned">Non affectée</span>'}</td><td><span class="ritm">${esc(r.ritm||'—')}</span></td><td><div class="activity-date" title="${esc(dateFull(r.last_message_at||r.updated_at))}">${esc(dateShort(r.last_message_at||r.updated_at))}</div><div class="activity-hint">${esc(r.application || r.source)}</div></td><td>${r.alert_count?`<button class="alert-flag" data-open="${r.id}" aria-label="${num(r.alert_count)} réponse à examiner" title="Réponse après clôture">${ico('alert')}</button>`:`<button class="icon-button" data-open="${r.id}" aria-label="Ouvrir ${esc(r.reference)}">${ico('chevron')}</button>`}</td></tr>`).join('')}</tbody></table></div>`;
  renderSelection();
}
function renderSelection(){const region=$('#selection-region');if(region)region.innerHTML=state.selected.size?`<div class="selection-bar"><span><strong>${num(state.selected.size)}</strong> demande${state.selected.size>1?'s':''} sélectionnée${state.selected.size>1?'s':''}</span><div style="display:flex;gap:12px"><button class="button link small" data-action="export" data-format="csv">Exporter CSV</button><button class="button link small" data-action="deselect">Tout désélectionner</button></div></div>`:'';}
function navigate(view){if(!view||!v2.beforeNavigate(view))return;state.view=view;state.filters=defaultFilters();state.selected.clear();state.importFiles=[];state.importResult=null;clearTimeout(searchTimer);state.listSeq++;$('.sidebar')?.classList.remove('open');renderPage();}

async function download(path,fallback){try{const result=await api(path,{blob:true});const url=URL.createObjectURL(result.blob);const a=document.createElement('a');a.href=url;a.download=result.filename||fallback;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){toast(error.message,true);}}
async function exportRequests(format='csv'){const selected=state.selected.size?{ids:[...state.selected].join(',')}:{};await download(`/api/export?${queryString({format,...selected})}`,`vigie-demandes.${format}`);}

function detailMessage(message){
  const sender=message.sender_name||message.sender||message.from_name||message.sender_email||'Expéditeur';
  const email=message.sender_email||message.from_email||'';const time=message.sent_at||message.received_at||message.date||message.created_at;const body=message.body||message.body_text||message.text||'';const attachments=message.attachments||[];const outlook=safeUrl(message.web_url||message.outlook_url||message.web_link||message.webLink);
  return `<article class="timeline-item"><div class="message-header"><div class="message-person"><div class="avatar">${esc(initials(sender))}</div><div><div class="message-name">${esc(sender)}</div>${email&&email!==sender?`<div class="message-email">${esc(email)}</div>`:''}<span class="message-type">${ico('mail')}${message.direction==='outbound'||message.direction==='sent'?'Mail envoyé':message.direction==='inbound'?'Mail reçu':'Message'}${message.is_reply?' · réponse':''}</span></div></div><time class="message-date">${esc(dateFull(time))}</time></div><div class="message-body">${message.subject?`<h4>${esc(message.subject)}</h4>`:''}<div class="plain-text">${esc(body||'Ce message ne contient pas de texte consultable.')}</div>${attachments.length?`<div>${attachments.map(a=>`<button class="attachment" data-attachment="${a.id}" data-name="${esc(a.name||a.filename||'piece-jointe')}">${ico('attachment')}${esc(a.name||a.filename||'Pièce jointe')}${a.size?` <span class="muted">(${num(Math.max(1,Math.round(a.size/1024)))} Ko)</span>`:''}</button>`).join(' ')}</div>`:''}</div><div class="message-actions">${outlook?`<a class="button link" href="${esc(outlook)}" target="_blank" rel="noopener noreferrer">${ico('external')}Ouvrir dans Outlook</a>`:''}<button class="button link" data-move-message="${message.id}">${ico('move')}Corriger le rattachement</button></div></article>`;
}
const fieldLabels={title:'Intitulé',description:'Description',status:'Statut',ritm:'RITM',assignee:'Affectation',priority:'Priorité',application:'Application',category:'Catégorie',environment:'Environnement',requester:'Demandeur',requester_email:'Adresse du demandeur',channel:'Canal',closed_at:'Date de clôture'};
function historyDescription(event){
  if(event.description)return esc(event.description);
  const actions={created:'Demande créée',create:'Demande créée',request_created:'Demande créée',updated:'Suivi mis à jour',update:'Suivi mis à jour',request_updated:'Suivi mis à jour',comment_added:'Commentaire interne ajouté',message_imported:'Message intégré',import:'Message intégré',message_moved:'Rattachement du message corrigé',message_moved_in:'Message rattaché à cette demande',message_moved_out:'Message déplacé vers une autre demande',alert_reviewed:'Réponse après clôture examinée',alerts_reviewed:'Réponse après clôture examinée',reopened:'Demande rouverte',closed:'Demande clôturée',history_imported:'Demande reprise depuis le suivi historique'};
  let text=actions[event.action]||event.action||'Événement de suivi';const changes=event.changes||event.details;
  if(changes&&typeof changes==='object'){const pairs=Array.isArray(changes)?changes.map(c=>[c.field,c]):Object.entries(changes);text+=pairs.filter(([k])=>!['version','updated_at'].includes(k)).map(([key,val])=>{if(val&&typeof val==='object'&&('before'in val||'old'in val||'from'in val)){const before=val.before??val.old??val.from??'Non renseigné';const after=val.after??val.new??val.to??'Non renseigné';return `\n${fieldLabels[key]||key} : ${before||'Non renseigné'} → ${after||'Non renseigné'}`;}if(typeof val==='string'||typeof val==='number')return `\n${fieldLabels[key]||key} : ${val}`;return '';}).join('');}
  return esc(text).replace(/\n/g,'<br>');
}
function timelineHTML(){
  if(!state.detail)return '';
  let items=[];
  if(['all','messages'].includes(state.timeline))items.push(...(state.detail.messages||[]).map(v=>({type:'message',time:v.sent_at||v.received_at||v.date||v.created_at,v})));
  if(['all','comments'].includes(state.timeline))items.push(...(state.detail.comments||[]).map(v=>({type:'comment',time:v.created_at,v})));
  if(['all','history'].includes(state.timeline))items.push(...(state.detail.history||[]).map(v=>({type:'history',time:v.created_at,v})));
  items.sort((a,b)=>(new Date(a.time).getTime()||0)-(new Date(b.time).getTime()||0));
  if(!items.length)return `<div class="empty-state" style="min-height:160px">${ico(state.timeline==='messages'?'mail':'history')}<p>${state.timeline==='messages'?'Aucun échange rattaché à cette demande.':'Aucun élément à afficher dans ce filtre.'}</p></div>`;
  return items.map(({type,v,time})=>type==='message'?detailMessage(v):type==='comment'?`<article class="timeline-item comment"><div class="message-header"><div class="message-person"><div class="avatar">${esc(initials(v.author||v.author_name))}</div><div><div class="message-name">${esc(v.author||v.author_name||'Utilisateur local')}</div><span class="message-type">${ico('lock')}Commentaire interne</span></div></div><time class="message-date">${esc(dateFull(time))}</time></div><div class="message-body plain-text">${esc(v.body||v.text)}</div></article>`:`<div class="history-item">${ico('history')}<div><strong>${esc(v.actor||v.author||'Système')}</strong> · ${historyDescription(v)}<time>${esc(dateFull(time))}</time></div></div>`).join('');
}
function assigneeInput(value='',listId='assignees') {return state.workspace==='local'?`<input name="assignee" list="${listId}" value="${esc(value)}" maxlength="200" placeholder="Non affectée · saisir un nom"><datalist id="${listId}">${optionValues(state.context.users,'',null)}</datalist>`:`<select name="assignee">${optionValues(state.context.users,value,'Non affectée')}</select>`;}
function detailFields(r){return v2.detailFields(r);}
function renderDetail(){
  if(!state.detail)return;const r=state.detail.request;const pending=(state.detail.alerts||[]).filter(a=>!a.reviewed_at);state.detailDirty=false;
  let backdrop=$('#detail-backdrop');if(!backdrop){backdrop=document.createElement('div');backdrop.id='detail-backdrop';backdrop.className='backdrop';$('#overlay-root').append(backdrop);}
  backdrop.innerHTML=`<section class="drawer" role="dialog" aria-modal="true" aria-labelledby="detail-title" tabindex="-1"><div class="drawer-topbar"><div>${ico('layers')}<span>Demandes</span><span>/</span><strong>${esc(r.reference)}</strong></div><div><button class="button link small" data-action="edit-identity">${ico('file')}Modifier la demande</button><button class="icon-button" data-action="close-detail" aria-label="Fermer la fiche">${ico('close')}</button></div></div><div class="drawer-body"><header class="detail-heading"><div style="display:flex;align-items:center;gap:10px"><span class="reference" style="margin:0">${esc(r.reference)}</span>${statusBadge(r.status)}${priorityBadge(r.priority)}</div><h2 id="detail-title">${esc(r.title)}</h2><div class="detail-meta"><span>${esc(r.requester||'Demandeur non renseigné')}${r.requester_email?` · ${esc(r.requester_email)}`:''}</span><span>·</span><span>${esc(r.source)}${r.channel?` / ${esc(r.channel)}`:''}</span></div></header><div class="detail-grid"><div class="detail-main">${pending.length||r.alert_count?`<div class="detail-alert">${ico('alert')}<div><strong>${num(pending.length||r.alert_count)} réponse${(pending.length||r.alert_count)>1?'s':''} après clôture à examiner</strong><p>La demande reste close jusqu’à une réouverture explicite.</p></div><button class="button small" data-action="review-alert">Examiner</button></div>`:''}${r.description?`<section class="detail-description"><h3>DESCRIPTION DE LA DEMANDE</h3><p class="plain-text">${esc(r.description)}</p></section>`:''}<div class="timeline-header"><h3>Fil de la demande</h3><div class="timeline-tabs" role="group" aria-label="Filtrer le fil de la demande">${[['all','Tout'],['messages','Échanges'],['comments','Commentaires'],['history','Historique']].map(([key,label])=>`<button data-timeline="${key}" class="${state.timeline===key?'active':''}" aria-pressed="${state.timeline===key}">${label}</button>`).join('')}</div></div><div class="timeline" id="timeline-region">${timelineHTML()}</div><form class="comment-form" id="comment-form"><label for="comment-body">${ico('lock')}Ajouter un commentaire interne</label><textarea id="comment-body" name="body" placeholder="Partagez une information utile au suivi…" required maxlength="20000"></textarea><div id="comment-error"></div><div class="comment-footer"><small>Visible dans Vigie. Aucun e-mail n’est envoyé.</small><button class="button primary small" type="submit">${ico('plus')}Ajouter</button></div></form></div><aside class="detail-sidebar" aria-label="Qualification et suivi">${detailFields(r)}</aside></div></div></section>`;
  document.body.style.overflow='hidden';v2.detailDecorate();
}
async function openDetail(id){
  if(state.detailDirty&&!confirm('Des modifications ne sont pas enregistrées. Ouvrir une autre demande ?'))return;
  state.drawerReturn=document.activeElement;state.detailId=Number(id);state.timeline='all';const ws=state.workspaceSeq;
  let backdrop=$('#detail-backdrop');if(!backdrop){backdrop=document.createElement('div');backdrop.id='detail-backdrop';backdrop.className='backdrop';$('#overlay-root').append(backdrop);}
  backdrop.innerHTML=`<section class="drawer" role="dialog" aria-modal="true" aria-label="Chargement de la demande"><div class="drawer-topbar">Chargement de la fiche<button class="icon-button" data-action="close-detail" aria-label="Fermer">${ico('close')}</button></div>${loadingList()}</section>`;document.body.style.overflow='hidden';
  try{const data=await api(`/api/requests/${id}`);if(ws!==state.workspaceSeq||state.detailId!==Number(id))return;state.detail=data;renderDetail();$('.drawer').focus();}catch(error){if(!$('#detail-backdrop'))return;$('.drawer').innerHTML=`<div class="drawer-topbar">Fiche indisponible<button class="icon-button" data-action="close-detail" aria-label="Fermer">${ico('close')}</button></div><div class="panel-body">${errorBox(error,'reload-detail')}</div>`;}
}
function closeDetail(force=false){if(!force&&state.detailDirty&&!confirm('Quitter cette fiche sans enregistrer les modifications ?'))return;$('#detail-backdrop')?.remove();state.detail=null;state.detailId=null;state.detailDirty=false;document.body.style.overflow='';if(state.drawerReturn?.isConnected)state.drawerReturn.focus();}
function openModal({title,subtitle='',content,footer,wide=false}){
  state.modalReturn=document.activeElement;$('#modal-backdrop')?.remove();const backdrop=document.createElement('div');backdrop.id='modal-backdrop';backdrop.className='modal-backdrop';backdrop.innerHTML=`<section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><header class="modal-header"><div><h2 id="modal-title">${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Fermer la fenêtre">${ico('close')}</button></header>${content}<footer class="modal-footer">${footer||'<button class="button" data-action="close-modal">Fermer</button>'}</footer></section>`;$('#overlay-root').append(backdrop);document.body.style.overflow='hidden';if(v2.isPreview()){const form=$('form',backdrop);if(form&&['new-request-form','edit-identity-form','review-alert-form','move-message-form','resolve-anomaly-form'].includes(form.id)){$$('button[type="submit"]',backdrop).forEach(b=>b.disabled=true);form.insertAdjacentHTML('afterbegin','<div class="v2-readonly-note">Aperçu du formulaire. Quittez l’aperçu pour enregistrer des données.</div>');}}requestAnimationFrame(()=>{const first=$('input:not([type=hidden]),textarea,select',backdrop);(first||$('.modal',backdrop)).focus();});
}
function closeModal(){const modal=$('#modal-backdrop');if(!modal)return;modal.remove();document.body.style.overflow=$('#detail-backdrop')?'hidden':'';if(state.modalReturn?.isConnected)state.modalReturn.focus();}
function newRequestModal(){v2.newRequestModal();}
function editIdentityModal(){v2.editIdentityModal();}
function reviewAlertModal(){const r=state.detail?.request;if(!r)return;openModal({title:'Examiner la réponse après clôture',subtitle:`${r.reference} · Une décision explicite et tracée dans l’historique.`,content:`<form id="review-alert-form" class="modal-content"><label class="radio-card"><input type="radio" name="decision" value="reopen" checked><div><strong>Rouvrir la demande</strong><span>Reprendre le traitement de cette sollicitation.</span></div></label><label class="radio-card"><input type="radio" name="decision" value="keep"><div><strong>Maintenir la clôture</strong><span>La réponse a été lue et ne nécessite pas de reprise.</span></div></label><label class="form-field">Note d’examen<textarea name="note" required maxlength="10000" placeholder="Précisez la décision prise et les suites éventuelles…"></textarea></label><div id="modal-error"></div></form>`,footer:'<button class="button" data-action="close-modal">Annuler</button><button class="button primary" form="review-alert-form" type="submit">Valider l’examen</button>'});v2.reviewOptions();}
async function moveMessageModal(id){
  const message=state.detail?.messages?.find(m=>String(m.id)===String(id));if(!message)return;
  openModal({title:'Corriger le rattachement',subtitle:'Déplacer ce message et ses pièces jointes vers une autre fiche.',content:`<form id="move-message-form" data-message="${id}" class="modal-content"><div class="modal-note"><strong>Message concerné</strong><br>${esc(message.subject||'Sans objet')}<br>Depuis ${esc(state.detail.request.reference)}. Un seul message sera déplacé.</div><label class="form-field">Destination<select name="destination_mode" id="move-destination-mode"><option value="existing">Une demande existante</option><option value="new">Créer une nouvelle demande</option></select></label><label class="form-field" id="move-existing-field">Demande cible<select name="target_request_id" id="move-target" required><option value="">Chargement des demandes…</option></select></label><label class="form-field" id="move-new-field" hidden>Intitulé de la nouvelle demande<input name="new_title" maxlength="300" value="${esc(message.subject||'')}"></label><label class="form-field">Motif de la correction<textarea name="reason" required maxlength="10000" placeholder="Expliquez pourquoi ce message appartient à une autre demande…"></textarea></label><div class="modal-note">La correction est conservée lors des prochains imports. Les historiques et les compteurs des deux demandes sont actualisés.</div><div id="modal-error"></div></form>`,footer:'<button class="button" data-action="close-modal">Annuler</button><button class="button primary" form="move-message-form" type="submit">Déplacer le message</button>'});
  try{const result=await api('/api/requests?view=all');if(!$('#move-target'))return;$('#move-target').innerHTML='<option value="">Choisir une demande…</option>'+(result.items||[]).filter(r=>r.id!==state.detailId).map(r=>`<option value="${r.id}">${esc(r.reference)} — ${esc(r.title)}</option>`).join('');}catch(error){$('#modal-error').innerHTML=errorBox(error,null);}
}
async function refreshAfterMutation(){const ws=state.workspaceSeq;const results=await Promise.allSettled([loadStats(),api('/api/context')]);if(ws!==state.workspaceSeq)return;if(results[1].status==='fulfilled'){state.context={...state.context,...results[1].value};const filter=$('[data-filter="assignee"]');if(filter)filter.innerHTML=v2.assigneeOptions(state.filters.assignee);}if(views.some(v=>v.id===state.view))await loadList();}
async function submitForm(form,event){
  event.preventDefault();if(v2.isPreview()){toast('Quittez l’aperçu pour enregistrer des données métier.',true);return;}const id=form.id,data=v2.formData(form);let submit=$(`[form="${id}"][type="submit"]`)||$('button[type="submit"]',form);const errorTarget=id==='detail-form'?'#detail-form-error':id==='comment-form'?'#comment-error':'#modal-error';if($(errorTarget))$(errorTarget).innerHTML='';if(submit)submit.disabled=true;
  try{
    if(id==='new-request-form'){const result=await api('/api/requests',{method:'POST',body:data});closeModal();toast('La demande a été créée.');await refreshAfterMutation();await openDetail(result.request?.id||result.id);}
    else if(id==='detail-form'||id==='edit-identity-form'){const result=await api(`/api/requests/${state.detailId}`,{method:'PATCH',body:{...data,version:state.detail.request.version}});state.detail=result;if(id==='edit-identity-form')closeModal();renderDetail();toast('Les modifications ont été enregistrées.');await refreshAfterMutation();}
    else if(id==='comment-form'){if(!data.body.trim())throw new Error('Saisissez un commentaire avant de l’ajouter.');const draft=state.detailDirty&&$('#detail-form')?Object.fromEntries(new FormData($('#detail-form'))):null;state.detail=await api(`/api/requests/${state.detailId}/comments`,{method:'POST',body:{body:data.body}});renderDetail();if(draft){for(const [key,value] of Object.entries(draft)){const field=$('#detail-form').elements.namedItem(key);if(field)field.value=value;}state.detailDirty=true;}toast('Le commentaire interne a été ajouté.');await refreshAfterMutation();}
    else if(id==='review-alert-form'){state.detail=await api(`/api/requests/${state.detailId}/alerts/review`,{method:'POST',body:{note:data.note,reopen:data.decision==='reopen'}});closeModal();renderDetail();toast(data.decision==='reopen'?'La réponse a été examinée et la demande rouverte.':'La réponse a été examinée. La demande reste close.');await refreshAfterMutation();}
    else if(id==='move-message-form'){const body={reason:data.reason};if(data.destination_mode==='new')body.new_title=data.new_title;else body.target_request_id=Number(data.target_request_id);await api(`/api/messages/${form.dataset.message}/move`,{method:'POST',body});closeModal();state.detail=await api(`/api/requests/${state.detailId}`);renderDetail();toast('Le rattachement du message a été corrigé.');await refreshAfterMutation();}
    else if(id==='resolve-anomaly-form'){await api(`/api/anomalies/${form.dataset.anomaly}/resolve`,{method:'POST',body:{target_request_id:Number(data.target_request_id)}});closeModal();toast('Le message a été rattaché à la demande.');await loadStats();renderImports();}
  }catch(error){if($(errorTarget))$(errorTarget).innerHTML=`<div class="form-error" role="alert">${error.status===409?'Cette fiche a été modifiée depuis son ouverture. Vos saisies sont conservées ici. Rechargez la fiche pour consulter la dernière version avant de réappliquer vos changements.':esc(error.message)}${error.status===409?'<br><button class="button small" type="button" data-action="reload-detail">Recharger la fiche</button>':''}</div>`;else toast(error.message,true);}
  finally{if(submit?.isConnected)submit.disabled=false;}
}

function renderReporting(){
  $('#main').innerHTML=`${heading('Pilotage','Une lecture synthétique de l’activité et des demandes à suivre.',false)}${modeBanner()}<div id="stats-region">${statsCards()}</div><div id="report-region">${loadingList()}</div>${pageFooter()}`;
  const ws=state.workspaceSeq;api('/api/stats').then(stats=>{if(ws!==state.workspaceSeq||state.view!=='reporting')return;state.stats=stats;updateNav();$('#stats-region').innerHTML=statsCards();$('#report-region').innerHTML=`<div class="report-grid">${barPanel('Répartition par statut','Toutes les demandes du périmètre',stats.by_status)}${barPanel('Charge par affectation','Nombre de demandes par responsable',stats.by_assignee)}${barPanel('Applications concernées','Qualification des demandes',stats.by_application)}${barPanel('Répartition par priorité','Priorités renseignées dans le suivi',stats.by_priority)}</div><section class="panel"><div class="panel-header"><div><h3>Données de reporting</h3><p>Une ligne par demande, issue de la même source que le suivi métier.</p></div><button class="button" data-action="report-export">${ico('import')}Exporter les données</button></div><div class="panel-body"><div class="setting-row"><span>Demandes suivies</span><strong>${num(stats.total)}</strong></div><div class="setting-row"><span>Messages intégrés</span><strong>${num(stats.message_count)}</strong></div><div class="setting-row"><span>Réponses identifiées</span><strong>${num(stats.reply_count)}</strong></div><div class="setting-row"><span>Messages à rapprocher</span><strong>${num(stats.unresolved)}</strong></div><div class="report-note" style="margin-top:15px">L’export JSON contient les exemples de votre démonstration. Le raccordement Power BI reste à configurer avec l’équipe IT dans la version complète.</div></div></section>`;}).catch(error=>{if($('#report-region'))$('#report-region').innerHTML=errorBox(error,'reload-page');});
}
function barPanel(title,subtitle,raw){const values=Array.isArray(raw)?raw:Object.entries(raw||{}).map(([label,value])=>({label,value}));const items=values.map(x=>({label:x.label??x.name??'Non renseigné',value:Number(x.value??x.count??0)}));const max=Math.max(1,...items.map(x=>x.value));return `<section class="panel"><div class="panel-header"><div><h3>${esc(title)}</h3><p>${esc(subtitle)}</p></div>${ico('chart')}</div><div class="panel-body">${items.length?`<div class="bar-list">${items.map((item,i)=>`<div><div class="bar-heading"><span>${esc(item.label||'Non renseigné')}</span><strong>${num(item.value)}</strong></div><div class="bar-track" role="img" aria-label="${esc(item.label)} : ${num(item.value)}"><div class="bar-fill" style="width:${Math.max(0,Math.min(100,item.value/max*100))}%"></div></div></div>`).join('')}</div>`:'<p class="muted text-small">Les indicateurs apparaîtront avec les premières demandes.</p>'}</div></section>`;}
function renderImports(){
  $('#main').innerHTML=`${heading('Imports & rapprochements','Intégrez vos échanges et reprenez votre suivi dans une source commune.',false)}${modeBanner()}<div class="import-grid"><section class="panel"><div class="panel-header"><div><h3>Importer des données</h3><p>Prévisualisez les fichiers, puis lancez leur intégration.</p></div>${ico('import')}</div><div class="panel-body"><div class="import-tabs" role="group" aria-label="Type d’import"><button class="import-tab ${state.importKind==='mail'?'active':''}" data-import-kind="mail">Échanges par e-mail</button><button class="import-tab ${state.importKind==='history'?'active':''}" data-import-kind="history">Historique de suivi</button></div><label class="dropzone" id="dropzone" for="import-files">${ico('import')}<strong>Choisir ${state.importKind==='mail'?'des messages à intégrer':'un fichier de suivi'}</strong><p>ou déposer vos fichiers dans cette zone</p><p>${state.importKind==='mail'?'Formats EML ou JSON · mails et pièces jointes':'Formats CSV ou XLSX · modèle de colonnes ci-dessous'}</p><input class="file-input" type="file" id="import-files" accept="${state.importKind==='mail'?'.eml,.json':'.csv,.xlsx'}" multiple></label><div id="import-files-region">${importFilesHTML()}</div><div class="import-actions"><button class="download-link" data-action="download-template">${ico('file')}Télécharger le modèle ${state.importKind==='mail'?'JSON':'CSV'}</button><button class="button primary" data-action="run-import" ${!state.importFiles.length?'disabled':''}>${ico('import')}Lancer l’import</button></div><div id="import-result">${importResultHTML()}</div></div></section><section class="panel"><div class="panel-header"><div><h3>${state.importKind==='mail'?'Des échanges bien rattachés':'Une reprise contrôlée'}</h3><p>Les règles appliquées à l’intégration</p></div></div><div class="panel-body import-instructions">${state.importKind==='mail'?'<p>Chaque message est intégré une seule fois. Les réponses sont rapprochées à partir des identifiants de message et de conversation.</p><p>Un rattachement ambigu reste à examiner. Un objet ou un RITM similaire ne suffit pas à fusionner deux demandes.</p><p>Une réponse après clôture déclenche un examen sans rouvrir automatiquement la demande.</p>':'<p>Utilisez les colonnes du modèle pour reprendre vos demandes depuis un fichier CSV ou Excel. Le fichier existant peut être adapté au modèle avant intégration.</p><p>Les nouvelles données sont importées dans l’espace actuellement sélectionné. Le résultat indique les créations, les doublons et les erreurs rencontrées.</p><p>Les changements de suivi déjà réalisés dans Vigie sont conservés lors des imports suivants.</p>'}<div class="report-note" style="margin-top:21px">${ico('info')} Outlook n’est pas connecté. Cet écran intègre les fichiers que vous choisissez sur votre poste.</div></div></section></div><section class="panel import-history"><div class="panel-header"><div><h3>Messages à rapprocher</h3><p>Choisissez une demande cible pour les échanges dont le rattachement est ambigu.</p></div><span class="count-pill" id="anomaly-count">—</span></div><div class="panel-body" id="anomalies-region">${loadingList()}</div></section><section class="panel import-history"><div class="panel-header"><div><h3>Historique des imports</h3><p>Résultats des dernières intégrations dans cet espace.</p></div><button class="button small" data-action="reload-page">${ico('refresh')}Actualiser</button></div><div class="panel-body" id="imports-history-region">${loadingList()}</div></section>${pageFooter()}`;
  loadImportHistory();bindDropzone();
}
function importFilesHTML(){return state.importFiles.length?`<div class="file-list">${state.importFiles.map(f=>`<div class="file-row"><span>${esc(f.name)}</span><small>${num(Math.max(1,Math.round(f.size/1024)))} Ko</small></div>`).join('')}</div><p class="text-small muted">${num(state.importFiles.length)} fichier${state.importFiles.length>1?'s':''} sélectionné${state.importFiles.length>1?'s':''} · vérifiez cette liste avant de lancer l’import.</p>`:'';}
function importResultHTML(){const r=state.importResult;if(!r)return '';const errors=r.errors||[];return `<div style="margin-top:22px"><h3 style="font-size:13px">Résultat de l’import</h3><div class="result-grid">${[['created_requests','Demandes créées'],['imported','Éléments intégrés'],['duplicates','Doublons ignorés'],['unresolved','À rapprocher']].map(([k,label])=>`<div class="result-cell"><strong>${num(r[k])}</strong><span>${label}</span></div>`).join('')}</div>${errors.length?`<div class="form-error" style="margin-top:12px">${errors.map(err=>esc(typeof err==='string'?err:err.message||err.error||JSON.stringify(err))).join('<br>')}</div>`:''}</div>`;}
function setImportFiles(files){const allowed=state.importKind==='mail'?/\.(eml|json)$/i:/\.(csv|xlsx)$/i;const valid=[...files].filter(f=>allowed.test(f.name));if(valid.length!==files.length)toast('Certains fichiers n’ont pas le format attendu pour cet import.',true);state.importFiles=valid;state.importResult=null;state.importPreview=null;state.encodedImportFiles=null;$('#import-files-region').innerHTML=importFilesHTML();$('#import-result').innerHTML='';$('[data-action="run-import"]').disabled=true;previewImportFiles();}
function bindDropzone(){const zone=$('#dropzone');if(!zone)return;zone.addEventListener('dragover',event=>{event.preventDefault();zone.classList.add('dragover');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragover'));zone.addEventListener('drop',event=>{event.preventDefault();zone.classList.remove('dragover');setImportFiles(event.dataTransfer.files);});}
async function loadImportHistory(){
  const ws=state.workspaceSeq;const results=await Promise.allSettled([api('/api/imports'),api('/api/anomalies')]);if(ws!==state.workspaceSeq||state.view!=='imports')return;
  if(results[0].status==='rejected')$('#imports-history-region').innerHTML=errorBox(results[0].reason,'reload-page');else{const items=results[0].value.items||[];$('#imports-history-region').innerHTML=items.length?`<div class="small-list">${items.map(row=>{let report=row.report||row.result||row.summary||row;try{if(typeof report==='string')report=JSON.parse(report);}catch{report={};}return `<div class="small-list-row"><div class="row-icon">${ico('import')}</div><div class="row-content"><h3>${esc(row.filename||row.name||(row.kind==='messages'?'Import de messages':row.kind==='history'?'Reprise du suivi historique':row.source||row.kind)||'Import de données')}</h3><p>${esc(dateFull(row.created_at||row.started_at))} · ${num(report.imported||report.imported_count)} intégrés · ${num(report.duplicates||report.duplicate_count)} doublons · ${num(report.unresolved||report.unresolved_count)} à rapprocher</p></div><span class="badge ${row.status==='failed'||row.status==='À vérifier'?'status-waiting':'status-progress'}">${row.status==='failed'?'Échec':row.status==='partial'||row.status==='À vérifier'?'À vérifier':'Terminé'}</span></div>`;}).join('')}</div>`:'<p class="muted text-small">Aucun import dans cet espace pour le moment.</p>';}
  if(results[1].status==='rejected')$('#anomalies-region').innerHTML=errorBox(results[1].reason,'reload-page');else{const items=(results[1].value.items||[]).filter(row=>!row.resolved_at&&row.status!=='resolved');$('#anomaly-count').textContent=num(items.length);$('#anomalies-region').innerHTML=items.length?`<div class="small-list">${items.map(row=>`<div class="small-list-row"><div class="row-icon">${ico('alert')}</div><div class="row-content"><h3>${esc(row.subject||row.message?.subject||'Message à rapprocher')}</h3><p>${esc(row.reason||row.description||'Le rattachement à une demande nécessite un examen.')}<br>${esc(row.sender_email||row.message?.sender_email||'')} · ${esc(dateFull(row.created_at))}</p></div><button class="button small" data-resolve-anomaly="${row.message_id||row.id}">Rapprocher</button></div>`).join('')}</div>`:'<div class="success-note">'+ico('checkcircle')+'Aucun message en attente de rapprochement.</div>';}
}
async function encodeImportFiles(files){
  const encoded=[];
  for(const file of files){
    if(file.size>12*1024*1024)throw new Error(`Le fichier ${file.name} dépasse 12 Mo. Réduisez sa taille pour cet import local.`);
    const bytes=new Uint8Array(await file.arrayBuffer());let binary='';
    for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));
    encoded.push({name:file.name,content_base64:btoa(binary)});
  }
  return encoded;
}
async function previewImportFiles(){
  const files=state.importFiles,kind=state.importKind,workspace=state.workspace,ws=state.workspaceSeq;
  state.importPreview=null;state.encodedImportFiles=null;
  if(!files.length)return;
  const region=$('#import-result');if(region)region.innerHTML='<p class="muted text-small" style="margin-top:18px" role="status">Lecture des fichiers et préparation de l’aperçu…</p>';
  try{
    const encoded=await encodeImportFiles(files);
    const preview=await api('/api/imports/preview',{method:'POST',body:{files:encoded,kind},workspace});
    if(ws!==state.workspaceSeq||files!==state.importFiles||kind!==state.importKind||state.view!=='imports')return;
    state.importPreview=preview;state.encodedImportFiles=encoded;
    const sample=preview.sample||[];const fields=kind==='mail'?[['subject','Objet'],['sender','Expéditeur'],['sent_at','Date']]:[['title','Intitulé'],['status','Statut'],['ritm','RITM']];
    $('#import-result').innerHTML=`<div style="margin-top:22px"><h3 style="font-size:13px">Aperçu avant intégration</h3><p class="muted text-small" style="margin:6px 0 12px">${num(preview.count)} élément${preview.count>1?'s':''} détecté${preview.count>1?'s':''}. ${preview.count>5?'Les 5 premiers sont affichés ci-dessous.':''}</p>${sample.length?`<div class="table-wrap import-preview"><table style="white-space:normal"><thead><tr>${fields.map(([,label])=>`<th scope="col">${label}</th>`).join('')}</tr></thead><tbody>${sample.map(row=>`<tr>${fields.map(([key])=>`<td style="max-width:230px;overflow-wrap:anywhere;padding:10px 12px">${esc(key==='sent_at'?dateFull(row[key]):row[key]||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="form-error">Aucun élément importable dans ces fichiers.</div>'}</div>`;
    const button=$('[data-action="run-import"]');if(button)button.disabled=!preview.count;
  }catch(error){if(ws!==state.workspaceSeq||files!==state.importFiles)return;if($('#import-result'))$('#import-result').innerHTML=`<div style="margin-top:15px">${errorBox(error,null)}</div>`;}
}
async function runImport(){
  if(v2.isPreview()){toast('Quittez l’aperçu pour importer des données.',true);return;}if(!state.importFiles.length||!state.importPreview?.count)return;const button=$('[data-action="run-import"]');button.disabled=true;button.innerHTML=`${ico('clock')}Import en cours…`;const workspace=state.workspace,ws=state.workspaceSeq;
  try{const files=state.encodedImportFiles||await encodeImportFiles(state.importFiles);const result=await api('/api/imports/files',{method:'POST',body:{files,kind:state.importKind},workspace});if(ws!==state.workspaceSeq)return;state.importResult=result;if($('#import-result'))$('#import-result').innerHTML=importResultHTML();toast(result.errors?.length?'Import terminé avec des éléments à vérifier.':'L’import est terminé.');await loadStats();await loadImportHistory();}catch(error){if($('#import-result'))$('#import-result').innerHTML=`<div style="margin-top:15px">${errorBox(error,null)}</div>`;else toast(error.message,true);}finally{if(button.isConnected){button.disabled=false;button.innerHTML=`${ico('import')}Lancer l’import`;}}
}
async function resolveAnomalyModal(id){openModal({title:'Rapprocher le message',subtitle:'Choisissez la demande à laquelle appartient cet échange.',content:`<form id="resolve-anomaly-form" data-anomaly="${id}" class="modal-content"><label class="form-field">Demande cible<select name="target_request_id" id="anomaly-target" required><option value="">Chargement…</option></select></label><div class="modal-note">Le message sera ajouté au fil de la demande choisie. Ce rapprochement sera conservé.</div><div id="modal-error"></div></form>`,footer:'<button class="button" data-action="close-modal">Annuler</button><button class="button primary" type="submit" form="resolve-anomaly-form">Rattacher le message</button>'});try{const result=await api('/api/requests?view=all');if($('#anomaly-target'))$('#anomaly-target').innerHTML='<option value="">Choisir une demande…</option>'+(result.items||[]).map(r=>`<option value="${r.id}">${esc(r.reference)} — ${esc(r.title)}</option>`).join('');}catch(error){if($('#modal-error'))$('#modal-error').innerHTML=errorBox(error,null);}}
function renderSettings(){
  const c=state.context;$('#main').innerHTML=`${heading('Paramètres','Le contexte de votre application et les référentiels du suivi.',false)}${modeBanner()}<div class="settings-grid"><section class="settings-card">${ico('database')}<h3>Deux espaces de données distincts</h3><p>L’espace de démonstration contient uniquement des exemples fictifs. L’espace local vous permet de créer et d’importer vos propres demandes. Les modifications sont enregistrées dans une base locale.</p><div class="setting-row"><span>Espace actif</span><strong>${state.workspace==='demo'?'Démonstration':'Espace local'}</strong></div><div class="setting-row"><span>Connexion au serveur</span><strong>Locale à ce poste</strong></div><div style="margin-top:15px"><button class="download-link" data-action="backup">${ico('import')}Télécharger une sauvegarde</button></div></section><section class="settings-card">${ico('person')}<h3>Identité de la session</h3><p>Les actions sont attribuées à la session locale. Cette version ne dispose pas d’une authentification d’entreprise ni d’une gestion multi-utilisateur raccordée à l’annuaire.</p><div class="setting-row"><span>Utilisateur</span><strong>${esc(c.actor?.name||'Utilisateur local')}</strong></div><span class="badge status-waiting">SSO d’entreprise non connecté</span></section><section class="settings-card">${ico('mail')}<h3>Messagerie Outlook</h3><p>Les messages EML et JSON peuvent être intégrés depuis l’écran Imports. La collecte automatique d’une boîte Outlook nécessite un connecteur et les accès validés par votre équipe IT.</p><span class="badge status-waiting">Collecte Outlook non connectée</span></section><section class="settings-card">${ico('chart')}<h3>Reporting & exports</h3><p>Exportez les vues ou les demandes sélectionnées en Excel ou CSV. La source JSON de reporting fournit une ligne par demande pour préparer le raccordement Power BI.</p><div style="margin-top:15px"><button class="download-link" data-action="report-export">${ico('import')}Télécharger la source JSON</button></div></section><section class="settings-card">${ico('layers')}<h3>Statuts & priorités</h3><p>Valeurs proposées pour le pilote métier. La clôture reste une décision explicite et le RITM est facultatif.</p><div class="tag-list">${(c.statuses||[]).map(s=>statusBadge(s)).join('')}</div><div class="tag-list">${(c.priorities||[]).map(s=>`<span>${esc(s)}</span>`).join('')}</div></section><section class="settings-card">${ico('settings')}<h3>Référentiels du pilote</h3><p>Applications et catégories disponibles pour qualifier les demandes. Ces listes sont configurées côté serveur pour ce pilote.</p><div class="tag-list">${(c.applications||[]).map(s=>`<span>${esc(labelValue(s))}</span>`).join('')}</div><div class="tag-list">${(c.categories||[]).map(s=>`<span>${esc(labelValue(s))}</span>`).join('')}</div></section></div>${pageFooter()}`;
}

document.addEventListener('click',async event=>{
  const target=event.target.closest('button,a');if(!target)return;
  if(target.dataset.view){navigate(target.dataset.view);return;}
  if(target.dataset.open){openDetail(target.dataset.open);return;}
  if(target.dataset.clearFilter){state.filters[target.dataset.clearFilter]='';state.selected.clear();renderPage();return;}
  if(target.dataset.timeline){state.timeline=target.dataset.timeline;$$('[data-timeline]').forEach(b=>{b.classList.toggle('active',b.dataset.timeline===state.timeline);b.setAttribute('aria-pressed',String(b.dataset.timeline===state.timeline));});$('#timeline-region').innerHTML=timelineHTML();return;}
  if(target.dataset.moveMessage){moveMessageModal(target.dataset.moveMessage);return;}
  if(target.dataset.attachment){download(`/api/attachments/${target.dataset.attachment}`,target.dataset.name||'piece-jointe');return;}
  if(target.dataset.resolveAnomaly){resolveAnomalyModal(target.dataset.resolveAnomaly);return;}
  if(target.dataset.importKind){state.importKind=target.dataset.importKind;state.importFiles=[];state.importResult=null;renderImports();return;}
  switch(target.dataset.action){
    case'new':newRequestModal();break;
    case'menu':$('.sidebar').classList.toggle('open');break;
    case'filters':state.moreFilters=!state.moreFilters;$('#more-filters').hidden=!state.moreFilters;target.setAttribute('aria-expanded',String(state.moreFilters));break;
    case'clear-filters':state.filters=defaultFilters();state.selected.clear();renderPage();break;
    case'retry-list':loadList();break;
    case'refresh':target.disabled=true;await Promise.allSettled([loadStats(),loadList()]);if(target.isConnected)target.disabled=false;break;
    case'export':exportRequests(target.dataset.format||'xlsx');break;
    case'deselect':state.selected.clear();renderTable();break;
    case'close-detail':closeDetail();break;
    case'close-modal':closeModal();break;
    case'edit-identity':editIdentityModal();break;
    case'review-alert':reviewAlertModal();break;
    case'reload-detail':{const id=state.detailId;if(state.detailDirty&&!confirm('Recharger la fiche effacera les modifications non enregistrées. Continuer ?'))break;state.detailDirty=false;closeModal();openDetail(id);break;}
    case'reload-page':renderPage();break;
    case'download-template':download(`/api/templates/${state.importKind==='mail'?'messages.json':'history.csv'}`,state.importKind==='mail'?'vigie-messages-modele.json':'vigie-historique-modele.csv');break;
    case'run-import':runImport();break;
    case'report-export':download('/api/reporting/requests','vigie-reporting-demandes.json');break;
    case'backup':download('/api/backup',`vigie-${state.workspace}-sauvegarde.sqlite3`);break;
  }
});
document.addEventListener('input',event=>{
  if(event.target.id==='search'){state.filters.q=event.target.value;state.selected.clear();renderFilterChips();clearTimeout(searchTimer);searchTimer=setTimeout(loadList,250);}
  if(event.target.closest('#detail-form'))state.detailDirty=true;
});
document.addEventListener('change',event=>{
  const target=event.target;
  if(target.id==='workspace-select'){changeWorkspace(target.value);return;}
  if(target.dataset.filter){state.filters[target.dataset.filter]=target.value;state.selected.clear();renderFilterChips();loadList();return;}
  if(target.id==='select-all'){state.selected=target.checked?new Set(state.items.map(r=>String(r.id))):new Set();renderTable();return;}
  if(target.dataset.select){target.checked?state.selected.add(target.dataset.select):state.selected.delete(target.dataset.select);target.closest('tr').classList.toggle('selected',target.checked);const all=$('#select-all');if(all){all.checked=state.selected.size===state.items.length;all.indeterminate=state.selected.size>0&&state.selected.size<state.items.length;}renderSelection();return;}
  if(target.id==='import-files'){setImportFiles(target.files);return;}
  if(target.id==='move-destination-mode'){const isNew=target.value==='new';$('#move-existing-field').hidden=isNew;$('#move-new-field').hidden=!isNew;$('#move-target').required=!isNew;$('input[name="new_title"]').required=isNew;}
  if(target.closest('#detail-form'))state.detailDirty=true;
});
document.addEventListener('submit',event=>{if(['new-request-form','detail-form','comment-form','edit-identity-form','review-alert-form','move-message-form','resolve-anomaly-form'].includes(event.target.id))submitForm(event.target,event);});
document.addEventListener('keydown',event=>{
  const dialog=$('#modal-backdrop .modal')||$('#detail-backdrop .drawer');
  if(event.key==='Escape'){if($('#modal-backdrop'))closeModal();else if($('#detail-backdrop'))closeDetail();else $('.sidebar')?.classList.remove('open');}
  if(event.key==='Tab'&&dialog){const focusables=$$('button:not([disabled]),[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]',dialog).filter(el=>el.offsetParent!==null);if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){event.preventDefault();first.focus();}}
});
window.addEventListener('beforeunload',event=>{if(state.detailDirty){event.preventDefault();event.returnValue='';}});

async function changeWorkspace(workspace){
  if(state.detailDirty&&!confirm('Changer d’espace abandonnera les modifications non enregistrées. Continuer ?')){$('#workspace-select').value=state.workspace;return;}
  state.workspace=workspace==='local'?'local':'demo';state.workspaceSeq++;state.listSeq++;state.stats={};state.selected.clear();state.filters=defaultFilters();state.importFiles=[];state.importResult=null;closeModal();closeDetail(true);try{localStorage.setItem('vigie-workspace',state.workspace);}catch{}await boot();
}
async function boot(){
  const ws=state.workspaceSeq;
  try{if(!await v2.ensureAuth())return;const context=await api('/api/context');if(ws!==state.workspaceSeq)return;state.context={statuses:['Ouvert','En cours','En attente','Clos'],priorities:['Basse','Normale','Haute','Urgente'],users:[],applications:[],categories:[],...context};v2.acceptContext();renderShell();await loadStats();}
  catch(error){if(error.status===401){await v2.expired();return;}$('#app').innerHTML=`<main class="boot-state"><span class="boot-logo">V</span><h2>Vigie n’a pas pu s’ouvrir</h2><p style="max-width:500px;text-align:center">${esc(error.message)}</p><button class="button primary" id="boot-retry">Réessayer</button></main>`;$('#boot-retry').addEventListener('click',boot);}
}
boot();
